//************************************
//* CUSTOM AUXILIARY FUNCTIONS
//*
//* Virtual table implementations may overload SQL functions by implementing
//* the sqlite3_module.xFindFunction() method.
//

struct Fts5Context {}

type Fts5_extension_function = fn (&Fts5ExtensionApi, &Fts5Context, &Sqlite3_context, int, &&Sqlite3_value)

struct Fts5PhraseIter {
	a &u8
	b &u8
}

//
//* EXTENSION API FUNCTIONS
//*
//* xUserData(pFts):
//*   Return a copy of the pUserData pointer passed to the xCreateFunction()
//*   API when the extension function was registered.
//*
//* xColumnTotalSize(pFts, iCol, pnToken):
//*   If parameter iCol is less than zero, set output variable *nToken
//*   to the total number of tokens in the FTS5 table. Or, if iCol is
//*   non-negative but less than the number of columns in the table, return
//*   the total number of tokens in column iCol, considering all rows in
//*   the FTS5 table.
//*
//*   If parameter iCol is greater than or equal to the number of columns
//*   in the table, SQLITE_RANGE is returned. Or, if an error occurs (e.g.
//*   an OOM condition or IO error), an appropriate SQLite error code is
//*   returned.
//*
//* xColumnCount(pFts):
//*   Return the number of columns in the table.
//*
//* xColumnSize(pFts, iCol, pnToken):
//*   If parameter iCol is less than zero, set output variable *nToken
//*   to the total number of tokens in the current row. Or, if iCol is
//*   non-negative but less than the number of columns in the table, set
//*   *nToken to the number of tokens in column iCol of the current row.
//*
//*   If parameter iCol is greater than or equal to the number of columns
//*   in the table, SQLITE_RANGE is returned. Or, if an error occurs (e.g.
//*   an OOM condition or IO error), an appropriate SQLite error code is
//*   returned.
//*
//*   This function may be quite inefficient if used with an FTS5 table
//*   created with the "columnsize=0" option.
//*
//* xColumnText:
//*   If parameter iCol is less than zero, or greater than or equal to the
//*   number of columns in the table, SQLITE_RANGE is returned.
//*
//*   Otherwise, this function attempts to retrieve the text of column iCol of
//*   the current document. If successful, (*z) is set to point to a buffer
//*   containing the text in utf-8 encoding, (*n) is set to the size in bytes
//*   (not characters) of the buffer and SQLITE_OK is returned. Otherwise,
//*   if an error occurs, an SQLite error code is returned and the final values
//*   of (*z) and (*n) are undefined.
//*
//* xPhraseCount:
//*   Returns the number of phrases in the current query expression.
//*
//* xPhraseSize:
//*   If parameter iCol is less than zero, or greater than or equal to the
//*   number of phrases in the current query, as returned by xPhraseCount,
//*   0 is returned. Otherwise, this function returns the number of tokens in
//*   phrase iPhrase of the query. Phrases are numbered starting from zero.
//*
//* xInstCount:
//*   Set *nInst to the total number of occurrences of all phrases within
//*   the query within the current row. Return SQLITE_OK if successful, or
//*   an error code (i.e. SQLITE_NOMEM) if an error occurs.
//*
//*   This API can be quite slow if used with an FTS5 table created with the
//*   "detail=none" or "detail=column" option. If the FTS5 table is created
//*   with either "detail=none" or "detail=column" and "content=" option
//*   (i.e. if it is a contentless table), then this API always returns 0.
//*
//* xInst:
//*   Query for the details of phrase match iIdx within the current row.
//*   Phrase matches are numbered starting from zero, so the iIdx argument
//*   should be greater than or equal to zero and smaller than the value
//*   output by xInstCount(). If iIdx is less than zero or greater than
//*   or equal to the value returned by xInstCount(), SQLITE_RANGE is returned.
//*
//*   Otherwise, output parameter *iPhrase is set to the phrase number, *iCol
//*   to the column in which it occurs and *iOff the token offset of the
//*   first token of the phrase. SQLITE_OK is returned if successful, or an
//*   error code (i.e. SQLITE_NOMEM) if an error occurs.
//*
//*   This API can be quite slow if used with an FTS5 table created with the
//*   "detail=none" or "detail=column" option.
//*
//* xRowid:
//*   Returns the rowid of the current row.
//*
//* xTokenize:
//*   Tokenize text using the tokenizer belonging to the FTS5 table.
//*
//* xQueryPhrase(pFts5, iPhrase, pUserData, xCallback):
//*   This API function is used to query the FTS table for phrase iPhrase
//*   of the current query. Specifically, a query equivalent to:
//*
//*       ... FROM ftstable WHERE ftstable MATCH $p ORDER BY rowid
//*
//*   with $p set to a phrase equivalent to the phrase iPhrase of the
//*   current query is executed. Any column filter that applies to
//*   phrase iPhrase of the current query is included in $p. For each
//*   row visited, the callback function passed as the fourth argument
//*   is invoked. The context and API objects passed to the callback
//*   function may be used to access the properties of each matched row.
//*   Invoking Api.xUserData() returns a copy of the pointer passed as
//*   the third argument to pUserData.
//*
//*   If parameter iPhrase is less than zero, or greater than or equal to
//*   the number of phrases in the query, as returned by xPhraseCount(),
//*   this function returns SQLITE_RANGE.
//*
//*   If the callback function returns any value other than SQLITE_OK, the
//*   query is abandoned and the xQueryPhrase function returns immediately.
//*   If the returned value is SQLITE_DONE, xQueryPhrase returns SQLITE_OK.
//*   Otherwise, the error code is propagated upwards.
//*
//*   If the query runs to completion without incident, SQLITE_OK is returned.
//*   Or, if some error occurs before the query completes or is aborted by
//*   the callback, an SQLite error code is returned.
//*
//*
//* xSetAuxdata(pFts5, pAux, xDelete)
//*
//*   Save the pointer passed as the second argument as the extension function's
//*   "auxiliary data". The pointer may then be retrieved by the current or any
//*   future invocation of the same fts5 extension function made as part of
//*   the same MATCH query using the xGetAuxdata() API.
//*
//*   Each extension function is allocated a single auxiliary data slot for
//*   each FTS query (MATCH expression). If the extension function is invoked
//*   more than once for a single FTS query, then all invocations share a
//*   single auxiliary data context.
//*
//*   If there is already an auxiliary data pointer when this function is
//*   invoked, then it is replaced by the new pointer. If an xDelete callback
//*   was specified along with the original pointer, it is invoked at this
//*   point.
//*
//*   The xDelete callback, if one is specified, is also invoked on the
//*   auxiliary data pointer after the FTS5 query has finished.
//*
//*   If an error (e.g. an OOM condition) occurs within this function,
//*   the auxiliary data is set to NULL and an error code returned. If the
//*   xDelete parameter was not NULL, it is invoked on the auxiliary data
//*   pointer before returning.
//*
//*
//* xGetAuxdata(pFts5, bClear)
//*
//*   Returns the current auxiliary data pointer for the fts5 extension
//*   function. See the xSetAuxdata() method for details.
//*
//*   If the bClear argument is non-zero, then the auxiliary data is cleared
//*   (set to NULL) before this function returns. In this case the xDelete,
//*   if any, is not invoked.
//*
//*
//* xRowCount(pFts5, pnRow)
//*
//*   This function is used to retrieve the total number of rows in the table.
//*   In other words, the same value that would be returned by:
//*
//*        SELECT count(* FROM ftstable;
//*
//* xPhraseFirst()
//*   This function is used, along with type Fts5PhraseIter and the xPhraseNext
//*   method, to iterate through all instances of a single query phrase within
//*   the current row. This is the same information as is accessible via the
//*   xInstCount/xInst APIs. While the xInstCount/xInst APIs are more convenient
//*   to use, this API may be faster under some circumstances. To iterate
//*   through instances of phrase iPhrase, use the following code:
//*
//*       Fts5PhraseIter iter;
//*       int iCol, iOff;
//*       for(pApi->xPhraseFirst(pFts, iPhrase, &iter, &iCol, &iOff);
//*           iCol>=0;
//*           pApi->xPhraseNext(pFts, &iter, &iCol, &iOff)
//*       ){
//*         // An instance of phrase iPhrase at offset iOff of column iCol
//*       }
//*
//*   The Fts5PhraseIter structure is defined above. Applications should not
//*   modify this structure directly - it should only be used as shown above
//*   with the xPhraseFirst() and xPhraseNext() API methods (and by
//*   xPhraseFirstColumn() and xPhraseNextColumn() as illustrated below).
//*
//*   This API can be quite slow if used with an FTS5 table created with the
//*   "detail=none" or "detail=column" option. If the FTS5 table is created
//*   with either "detail=none" or "detail=column" and "content=" option
//*   (i.e. if it is a contentless table), then this API always iterates
//*   through an empty set (all calls to xPhraseFirst() set iCol to -1).
//*
//*   In all cases, matches are visited in (column ASC, offset ASC) order.
//*   i.e. all those in column 0, sorted by offset, followed by those in
//*   column 1, etc.
//*
//* xPhraseNext()
//*   See xPhraseFirst above.
//*
//* xPhraseFirstColumn()
//*   This function and xPhraseNextColumn() are similar to the xPhraseFirst()
//*   and xPhraseNext() APIs described above. The difference is that instead
//*   of iterating through all instances of a phrase in the current row, these
//*   APIs are used to iterate through the set of columns in the current row
//*   that contain one or more instances of a specified phrase. For example:
//*
//*       Fts5PhraseIter iter;
//*       int iCol;
//*       for(pApi->xPhraseFirstColumn(pFts, iPhrase, &iter, &iCol);
//*           iCol>=0;
//*           pApi->xPhraseNextColumn(pFts, &iter, &iCol)
//*       ){
//*         // Column iCol contains at least one instance of phrase iPhrase
//*       }
//*
//*   This API can be quite slow if used with an FTS5 table created with the
//*   "detail=none" option. If the FTS5 table is created with either
//*   "detail=none" "content=" option (i.e. if it is a contentless table),
//*   then this API always iterates through an empty set (all calls to
//*   xPhraseFirstColumn() set iCol to -1).
//*
//*   The information accessed using this API and its companion
//*   xPhraseFirstColumn() may also be obtained using xPhraseFirst/xPhraseNext
//*   (or xInst/xInstCount). The chief advantage of this API is that it is
//*   significantly more efficient than those alternatives when used with
//*   "detail=column" tables.
//*
//* xPhraseNextColumn()
//*   See xPhraseFirstColumn above.
//*
//* xQueryToken(pFts5, iPhrase, iToken, ppToken, pnToken)
//*   This is used to access token iToken of phrase iPhrase of the current
//*   query. Before returning, output parameter *pToken is set to point
//*   to a buffer containing the requested token, and *nToken to the
//*   size of this buffer in bytes.
//*
//*   If iPhrase or iToken are less than zero, or if iPhrase is greater than
//*   or equal to the number of phrases in the query as reported by
//*   xPhraseCount(), or if iToken is equal to or greater than the number of
//*   tokens in the phrase, SQLITE_RANGE is returned and *pToken and *nToken
//     are both zeroed.
//*
//*   The output text is not a copy of the query text that specified the
//*   token. It is the output of the tokenizer module. For tokendata=1
//*   tables, this includes any embedded 0x00 and trailing data.
//*
//* xInstToken(pFts5, iIdx, iToken, ppToken, pnToken)
//*   This is used to access token iToken of phrase hit iIdx within the
//*   current row. If iIdx is less than zero or greater than or equal to the
//*   value returned by xInstCount(), SQLITE_RANGE is returned.  Otherwise,
//*   output variable (*pToken) is set to point to a buffer containing the
//*   matching document token, and (*nToken) to the size of that buffer in
//*   bytes.
//*
//*   The output text is not a copy of the document text that was tokenized.
//*   It is the output of the tokenizer module. For tokendata=1 tables, this
//*   includes any embedded 0x00 and trailing data.
//*
//*   This API may be slow in some cases if the token identified by parameters
//*   iIdx and iToken matched a prefix token in the query. In most cases, the
//*   first call to this API for each prefix token in the query is forced
//*   to scan the portion of the full-text index that matches the prefix
//*   token to collect the extra data required by this API. If the prefix
//*   token matches a large number of token instances in the document set,
//*   this may be a performance problem.
//*
//*   If the user knows in advance that a query may use this API for a
//*   prefix token, FTS5 may be configured to collect all required data as part
//*   of the initial querying of the full-text index, avoiding the second scan
//*   entirely. This also causes prefix queries that do not use this API to
//*   run more slowly and use more memory. FTS5 may be configured in this way
//*   either on a per-table basis using the [FTS5 insttoken | 'insttoken']
//*   option, or on a per-query basis using the
//*   [fts5_insttoken | fts5_insttoken()] user function.
//*
//*   This API can be quite slow if used with an FTS5 table created with the
//*   "detail=none" or "detail=column" option.
//*
//* xColumnLocale(pFts5, iIdx, pzLocale, pnLocale)
//*   If parameter iCol is less than zero, or greater than or equal to the
//*   number of columns in the table, SQLITE_RANGE is returned.
//*
//*   Otherwise, this function attempts to retrieve the locale associated
//*   with column iCol of the current row. Usually, there is no associated
//*   locale, and output parameters (*zLocale) and (*nLocale) are set
//*   to NULL and 0, respectively. However, if the fts5_locale() function
//*   was used to associate a locale with the value when it was inserted
//*   into the fts5 table, then (*zLocale) is set to point to a nul-terminated
//*   buffer containing the name of the locale in utf-8 encoding. (*nLocale)
//*   is set to the size in bytes of the buffer, not including the
//*   nul-terminator.
//*
//*   If successful, SQLITE_OK is returned. Or, if an error occurs, an
//*   SQLite error code is returned. The final value of the output parameters
//*   is undefined in this case.
//*
//* xTokenize_v2:
//*   Tokenize text using the tokenizer belonging to the FTS5 table. This
//*   API is the same as the xTokenize() API, except that it allows a tokenizer
//*   locale to be specified.
//

struct Fts5ExtensionApi {
	iVersion int
	// Currently always set to 4
	xUserData          fn (&Fts5Context) voidptr
	xColumnCount       fn (&Fts5Context) int
	xRowCount          fn (&Fts5Context, &Sqlite3_int64) int
	xColumnTotalSize   fn (&Fts5Context, int, &Sqlite3_int64) int
	xTokenize          fn (&Fts5Context, &i8, int, voidptr, fn (voidptr, int, &i8, int, int, int) int) int
	xPhraseCount       fn (&Fts5Context) int
	xPhraseSize        fn (&Fts5Context, int) int
	xInstCount         fn (&Fts5Context, &int) int
	xInst              fn (&Fts5Context, int, &int, &int, &int) int
	xRowid             fn (&Fts5Context) Sqlite3_int64
	xColumnText        fn (&Fts5Context, int, &&u8, &int) int
	xColumnSize        fn (&Fts5Context, int, &int) int
	xQueryPhrase       fn (&Fts5Context, int, voidptr, fn (&Fts5ExtensionApi, &Fts5Context, voidptr) int) int
	xSetAuxdata        fn (&Fts5Context, voidptr, fn (voidptr)) int
	xGetAuxdata        fn (&Fts5Context, int) voidptr
	xPhraseFirst       fn (&Fts5Context, int, &Fts5PhraseIter, &int, &int) int
	xPhraseNext        fn (&Fts5Context, &Fts5PhraseIter, &int, &int)
	xPhraseFirstColumn fn (&Fts5Context, int, &Fts5PhraseIter, &int) int
	xPhraseNextColumn  fn (&Fts5Context, &Fts5PhraseIter, &int)
	// Below this point are iVersion>=3 only
	xQueryToken fn (&Fts5Context, int, int, &&u8, &int) int
	xInstToken  fn (&Fts5Context, int, int, &&u8, &int) int
	// Below this point are iVersion>=4 only
	xColumnLocale fn (&Fts5Context, int, &&u8, &int) int
	xTokenize_v2  fn (&Fts5Context, &i8, int, &i8, int, voidptr, fn (voidptr, int, &i8, int, int, int) int) int
}

//
//* CUSTOM AUXILIARY FUNCTIONS
//************************************

//************************************
//* CUSTOM TOKENIZERS
//*
//* Applications may also register custom tokenizer types. A tokenizer
//* is registered by providing fts5 with a populated instance of the
//* following structure. All structure methods must be defined, setting
//* any member of the fts5_tokenizer struct to NULL leads to undefined
//* behaviour. The structure methods are expected to function as follows:
//*
//* xCreate:
//*   This function is used to allocate and initialize a tokenizer instance.
//*   A tokenizer instance is required to actually tokenize text.
//*
//*   The first argument passed to this function is a copy of the (void*
//*   pointer provided by the application when the fts5_tokenizer_v2 object
//*   was registered with FTS5 (the third argument to xCreateTokenizer()).
//*   The second and third arguments are an array of nul-terminated strings
//*   containing the tokenizer arguments, if any, specified following the
//*   tokenizer name as part of the CREATE VIRTUAL TABLE statement used
//*   to create the FTS5 table.
//*
//*   The final argument is an output variable. If successful, (*pOut)
//*   should be set to point to the new tokenizer handle and SQLITE_OK
//*   returned. If an error occurs, some value other than SQLITE_OK should
//*   be returned. In this case, fts5 assumes that the final value of *pOut
//*   is undefined.
//*
//* xDelete:
//*   This function is invoked to delete a tokenizer handle previously
//*   allocated using xCreate(). Fts5 guarantees that this function will
//*   be invoked exactly once for each successful call to xCreate().
//*
//* xTokenize:
//*   This function is expected to tokenize the nText byte string indicated
//*   by argument pText. pText may or may not be nul-terminated. The first
//*   argument passed to this function is a pointer to an Fts5Tokenizer object
//*   returned by an earlier call to xCreate().
//*
//*   The third argument indicates the reason that FTS5 is requesting
//*   tokenization of the supplied text. This is always one of the following
//*   four values:
//*
//*   <ul><li> <b>FTS5_TOKENIZE_DOCUMENT</b> - A document is being inserted into
//*            or removed from the FTS table. The tokenizer is being invoked to
//*            determine the set of tokens to add to (or delete from) the
//*            FTS index.
//*
//*       <li> <b>FTS5_TOKENIZE_QUERY</b> - A MATCH query is being executed
//*            against the FTS index. The tokenizer is being called to tokenize
//*            a bareword or quoted string specified as part of the query.
//*
//*       <li> <b>(FTS5_TOKENIZE_QUERY | FTS5_TOKENIZE_PREFIX)</b> - Same as
//*            FTS5_TOKENIZE_QUERY, except that the bareword or quoted string is
//*            followed by a "* character, indicating that the last token
//*            returned by the tokenizer will be treated as a token prefix.
//*
//*       <li> <b>FTS5_TOKENIZE_AUX</b> - The tokenizer is being invoked to
//*            satisfy an fts5_api.xTokenize() request made by an auxiliary
//*            function. Or an fts5_api.xColumnSize() request made by the same
//*            on a columnsize=0 database.
//*   </ul>
//*
//*   The sixth and seventh arguments passed to xTokenize() - pLocale and
//*   nLocale - are a pointer to a buffer containing the locale to use for
//*   tokenization (e.g. "en_US") and its size in bytes, respectively. The
//*   pLocale buffer is not nul-terminated. pLocale may be passed NULL (in
//*   which case nLocale is always 0) to indicate that the tokenizer should
//*   use its default locale.
//*
//*   For each token in the input string, the supplied callback xToken() must
//*   be invoked. The first argument to it should be a copy of the pointer
//*   passed as the second argument to xTokenize(). The third and fourth
//*   arguments are a pointer to a buffer containing the token text, and the
//*   size of the token in bytes. The 4th and 5th arguments are the byte offsets
//*   of the first byte of and first byte immediately following the text from
//*   which the token is derived within the input.
//*
//*   The second argument passed to the xToken() callback ("tflags") should
//*   normally be set to 0. The exception is if the tokenizer supports
//*   synonyms. In this case see the discussion below for details.
//*
//*   FTS5 assumes the xToken() callback is invoked for each token in the
//*   order that they occur within the input text.
//*
//*   If an xToken() callback returns any value other than SQLITE_OK, then
//*   the tokenization should be abandoned and the xTokenize() method should
//*   immediately return a copy of the xToken() return value. Or, if the
//*   input buffer is exhausted, xTokenize() should return SQLITE_OK. Finally,
//*   if an error occurs with the xTokenize() implementation itself, it
//*   may abandon the tokenization and return any error code other than
//*   SQLITE_OK or SQLITE_DONE.
//*
//*   If the tokenizer is registered using an fts5_tokenizer_v2 object,
//*   then the xTokenize() method has two additional arguments - pLocale
//*   and nLocale. These specify the locale that the tokenizer should use
//*   for the current request. If pLocale and nLocale are both 0, then the
//*   tokenizer should use its default locale. Otherwise, pLocale points to
//*   an nLocale byte buffer containing the name of the locale to use as utf-8
//*   text. pLocale is not nul-terminated.
//*
//* FTS5_TOKENIZER
//*
//* There is also an fts5_tokenizer object. This is an older, deprecated,
//* version of fts5_tokenizer_v2. It is similar except that:
//*
//*  <ul>
//*    <li> There is no "iVersion" field, and
//*    <li> The xTokenize() method does not take a locale argument.
//*  </ul>
//*
//* Legacy fts5_tokenizer tokenizers must be registered using the
//* legacy xCreateTokenizer() function, instead of xCreateTokenizer_v2().
//*
//* Tokenizer implementations registered using either API may be retrieved
//* using both xFindTokenizer() and xFindTokenizer_v2().
//*
//* SYNONYM SUPPORT
//*
//*   Custom tokenizers may also support synonyms. Consider a case in which a
//*   user wishes to query for a phrase such as "first place". Using the
//*   built-in tokenizers, the FTS5 query 'first + place' will match instances
//*   of "first place" within the document set, but not alternative forms
//*   such as "1st place". In some applications, it would be better to match
//*   all instances of "first place" or "1st place" regardless of which form
//*   the user specified in the MATCH query text.
//*
//*   There are several ways to approach this in FTS5:
//*
//*   <ol><li> By mapping all synonyms to a single token. In this case, using
//*            the above example, this means that the tokenizer returns the
//*            same token for inputs "first" and "1st". Say that token is in
//*            fact "first", so that when the user inserts the document "I won
//*            1st place" entries are added to the index for tokens "i", "won",
//*            "first" and "place". If the user then queries for '1st + place',
//*            the tokenizer substitutes "first" for "1st" and the query works
//*            as expected.
//*
//*       <li> By querying the index for all synonyms of each query term
//*            separately. In this case, when tokenizing query text, the
//*            tokenizer may provide multiple synonyms for a single term
//*            within the document. FTS5 then queries the index for each
//*            synonym individually. For example, faced with the query:
//*
//*   <codeblock>
//*     ... MATCH 'first place'</codeblock>
//*
//*            the tokenizer offers both "1st" and "first" as synonyms for the
//*            first token in the MATCH query and FTS5 effectively runs a query
//*            similar to:
//*
//*   <codeblock>
//*     ... MATCH '(first OR 1st) place'</codeblock>
//*
//*            except that, for the purposes of auxiliary functions, the query
//*            still appears to contain just two phrases - "(first OR 1st)"
//*            being treated as a single phrase.
//*
//*       <li> By adding multiple synonyms for a single term to the FTS index.
//*            Using this method, when tokenizing document text, the tokenizer
//*            provides multiple synonyms for each token. So that when a
//*            document such as "I won first place" is tokenized, entries are
//*            added to the FTS index for "i", "won", "first", "1st" and
//*            "place".
//*
//*            This way, even if the tokenizer does not provide synonyms
//*            when tokenizing query text (it should not - to do so would be
//*            inefficient), it doesn't matter if the user queries for
//*            'first + place' or '1st + place', as there are entries in the
//*            FTS index corresponding to both forms of the first token.
//*   </ol>
//*
//*   Whether it is parsing document or query text, any call to xToken that
//*   specifies a <i>tflags</i> argument with the FTS5_TOKEN_COLOCATED bit
//*   is considered to supply a synonym for the previous token. For example,
//*   when parsing the document "I won first place", a tokenizer that supports
//*   synonyms would call xToken() 5 times, as follows:
//*
//*   <codeblock>
//*       xToken(pCtx, 0, "i",                      1,  0,  1);
//*       xToken(pCtx, 0, "won",                    3,  2,  5);
//*       xToken(pCtx, 0, "first",                  5,  6, 11);
//*       xToken(pCtx, FTS5_TOKEN_COLOCATED, "1st", 3,  6, 11);
//*       xToken(pCtx, 0, "place",                  5, 12, 17);
//*</codeblock>
//*
//*   It is an error to specify the FTS5_TOKEN_COLOCATED flag the first time
//*   xToken() is called. Multiple synonyms may be specified for a single token
//*   by making multiple calls to xToken(FTS5_TOKEN_COLOCATED) in sequence.
//*   There is no limit to the number of synonyms that may be provided for a
//*   single token.
//*
//*   In many cases, method (1) above is the best approach. It does not add
//*   extra data to the FTS index or require FTS5 to query for multiple terms,
//*   so it is efficient in terms of disk space and query speed. However, it
//*   does not support prefix queries very well. If, as suggested above, the
//*   token "first" is substituted for "1st" by the tokenizer, then the query:
//*
//*   <codeblock>
//*     ... MATCH '1s*</codeblock>
//*
//*   will not match documents that contain the token "1st" (as the tokenizer
//*   will probably not map "1s" to any prefix of "first").
//*
//*   For full prefix support, method (3) may be preferred. In this case,
//*   because the index contains entries for both "first" and "1st", prefix
//*   queries such as 'fi* or '1s* will match correctly. However, because
//*   extra entries are added to the FTS index, this method uses more space
//*   within the database.
//*
//*   Method (2) offers a midpoint between (1) and (3). Using this method,
//*   a query such as '1s* will match documents that contain the literal
//*   token "1st", but not "first" (assuming the tokenizer is not able to
//*   provide synonyms for prefixes). However, a non-prefix query like '1st'
//*   will match against "1st" and "first". This method does not require
//*   extra disk space, as no extra entries are added to the FTS index.
//*   On the other hand, it may require more CPU cycles to run MATCH queries,
//*   as separate queries of the FTS index are required for each synonym.
//*
//*   When using methods (2) or (3), it is important that the tokenizer only
//*   provide synonyms when tokenizing document text (method (3)) or query
//*   text (method (2)), not both. Doing so will not cause any errors, but is
//*   inefficient.
//

struct Fts5Tokenizer {}

struct Fts5_tokenizer_v2 {
	iVersion int
	// Currently always 2
	xCreate   fn (voidptr, &&u8, int, &&Fts5Tokenizer) int
	xDelete   fn (&Fts5Tokenizer)
	xTokenize fn (&Fts5Tokenizer, voidptr, int, &i8, int, &i8, int, fn (voidptr, int, &i8, int, int, int) int) int
}

//
//* New code should use the fts5_tokenizer_v2 type to define tokenizer
//* implementations. The following type is included for legacy applications
//* that still use it.
//

struct Fts5_tokenizer {
	xCreate   fn (voidptr, &&u8, int, &&Fts5Tokenizer) int
	xDelete   fn (&Fts5Tokenizer)
	xTokenize fn (&Fts5Tokenizer, voidptr, int, &i8, int, fn (voidptr, int, &i8, int, int, int) int) int
}

// Flags that may be passed as the third argument to xTokenize()

// Flags that may be passed by the tokenizer implementation back to FTS5
//* as the third argument to the supplied xToken callback.

// Same position as prev. token

//
//* END OF CUSTOM TOKENIZERS
//************************************

//************************************
//* FTS5 EXTENSION REGISTRATION API
//

struct Fts5_api {
	iVersion int
	// Currently always set to 3

	// Create a new tokenizer
	xCreateTokenizer fn (&Fts5_api, &i8, voidptr, &Fts5_tokenizer, fn (voidptr)) int
	// Find an existing tokenizer
	xFindTokenizer fn (&Fts5_api, &i8, &voidptr, &Fts5_tokenizer) int
	// Create a new auxiliary function
	xCreateFunction fn (&Fts5_api, &i8, voidptr, Fts5_extension_function, fn (voidptr)) int
	// APIs below this point are only available if iVersion>=3

	// Create a new tokenizer
	xCreateTokenizer_v2 fn (&Fts5_api, &i8, voidptr, &Fts5_tokenizer_v2, fn (voidptr)) int
	// Find an existing tokenizer
	xFindTokenizer_v2 fn (&Fts5_api, &i8, &voidptr, &&Fts5_tokenizer_v2) int
}

//
//* END OF REGISTRATION API
