}

union ExprList_item_u {
	x             ExprList_item_u_x
	iConstExprReg int
	// Register in which Expr value is cached. Used only
	//                           * by Parse.pConstExpr
}

struct ExprList_item {
	// For each expression in the list
	pExpr &Expr
	// The parse tree for this expression
