//
//* The SrcItem object represents a single term in the FROM clause of a query.
//* The SrcList object is mostly an array of SrcItems.
//*
//* The jointype starts out showing the join type between the current table
//* and the next table on the list.  The parser builds the list this way.
//* But sqlite3SrcListShiftJoinType() later shifts the jointypes so that each
//* jointype expresses the join between the table and the previous table.
//*
//* In the colUsed field, the high-order bit (bit 63) is set if the table
//* contains more than 63 columns and the 64-th or later column is used.
//*
//* Aggressive use of "union" helps keep the size of the object small.  This
//* has been shown to boost performance, in addition to saving memory.
//* Access to union elements is gated by the following rules which should
//* always be checked, either by an if-statement or by an assert().
//*
//*    Field              Only access if this is true
//*    ---------------    -----------------------------------
//*    u1.zIndexedBy      fg.isIndexedBy
//*    u1.pFuncArg        fg.isTabFunc
//*    u1.nRow            !fg.isTabFunc  && !fg.isIndexedBy
//*
//*    u2.pIBIndex        fg.isIndexedBy
//*    u2.pCteUse         fg.isCte
//*
//*    u3.pOn             !fg.isUsing
//*    u3.pUsing          fg.isUsing
//*
//*    u4.zDatabase       !fg.fixedSchema && !fg.isSubquery
//*    u4.pSchema         fg.fixedSchema
//*    u4.pSubq           fg.isSubquery
//*
//* See also the sqlite3SrcListDelete() routine for assert() statements that
//* check invariants on the fields of this object, especially the flags
//* inside the fg struct.
//

struct SrcItem_fg {
	jointype U8
	// Type of join between this table and the previous
	notIndexed u32
	// True if there is a NOT INDEXED clause
	isIndexedBy u32
	// True if there is an INDEXED BY clause
	isSubquery u32
	// True if this term is a subquery
	isTabFunc u32
	// True if table-valued-function syntax
	isCorrelated u32
	// True if sub-query is correlated
	isMaterialized u32
	// This is a materialized view
	viaCoroutine u32
	// Implemented as a co-routine
	isRecursive u32
	// True for recursive reference in WITH
	fromDDL u32
	// Comes from sqlite_schema
	isCte u32
	// This is a CTE
	notCte u32
	// This item may not match a CTE
	isUsing u32
	// u3.pUsing is valid
	isOn u32
	// u3.pOn was once valid and non-NULL
	isSynthUsing u32
	// u3.pUsing is synthesized from NATURAL
	isNestedFrom u32
	// pSelect is a SF_NestedFrom subquery
	rowidUsed u32
	// The ROWID of this table is referenced
	fixedSchema u32
	// Uses u4.pSchema, not u4.zDatabase
	hadSchema u32
	// Had u4.zDatabase before u4.pSchema
	fromExists u32
	// Comes from WHERE EXISTS(...)
}

union SrcItem_u1 {
	zIndexedBy &i8
	// Identifier from "INDEXED BY <zIndex>" clause
	pFuncArg &ExprList
	// Arguments to table-valued-function
	nRow u32
	// Number of rows in a VALUES clause
}

union SrcItem_u2 {
	pIBIndex &Index
	// Index structure corresponding to u1.zIndexedBy
	pCteUse &CteUse
	// CTE Usage info when fg.isCte is true
}

union SrcItem_u3 {
	pOn &Expr
	// fg.isUsing==0 =>  The ON clause of a join
	pUsing &IdList
	// fg.isUsing==1 =>  The USING clause of a join
}

union SrcItem_u4 {
	pSchema &Schema
	// Schema to which this item is fixed
	zDatabase &i8
	// Name of database holding this table
	pSubq &Subquery
	// Description of a subquery
}

struct SrcItem {
	zName &i8
	// Name of the table
	zAlias &i8
	// The "B" part of a "A AS B" phrase.  zName is the "A"
