	// Table object for zName. Mnemonic: Srcitem-TABle
	fg      SrcItem_fg
	iCursor int
	// The VDBE cursor number used to access this table
	colUsed Bitmask
	// Bit N set if column N used. Details above for N>62
	u1 SrcItem_u1
	u2 SrcItem_u2
	u3 SrcItem_u3
	u4 SrcItem_u4
}

