			}
			unsafe { *p_highwtr = Sqlite3_int64(0) }
			unsafe { *p_current = Sqlite3_int64(n_ret_2) }

			// Set *Current to non-zero if there are unresolved deferred foreign
			//    * key constraints.  Set *Current to zero if all foreign key constraints
			//    * have been satisfied.  The *Highwtr is always set to zero.
			//
		}
		10 {
			// case comp stmt
			unsafe { *p_highwtr = Sqlite3_int64(0) }

			// IMP: R-11967-56545

			unsafe { *p_current = Sqlite3_int64(db.nDeferredImmCons > I64(0) || db.nDeferredCons > I64(0)) }
		}
		else {
