	x := DateTime{}
	i := usize(0)
	j := usize(0)

	db := &Sqlite3(0)
	z_fmt := &i8(0)
	s_res := Sqlite3_str{}
	if argc == 0 {
		return
	}
	z_fmt = &i8(voidptr(sqlite3_value_text(argv[0])))
	if usize(z_fmt) == usize(0) || is_date(context, argc - 1, argv + 1, &x) {
		return
