	db = sqlite3_context_db_handle(context)
	sqlite3_str_accum_init(unsafe { &StrAccum(&s_res) }, unsafe { nil }, unsafe { nil }, 0, db.aLimit[0])
	compute_jd(&x)
	compute_ymd_hms(&x)
	j = usize(0)
	for i = usize(0); z_fmt[i]; i++ {
		cf := i8(0)
		if int(z_fmt[i]) != i8(`%`) {
			continue
		}
		if j < i {
			sqlite3_str_append(&s_res, z_fmt + j, int((i - j)))
		}
		i++
		j = i + usize(1)
		cf = z_fmt[i]
