			}
			int(`f`) {
				// case comp stmt
				// Fractional seconds.  (Non-standard)

				s := x.s
				if (s > 59.999000000000002) {
					s = 59.999000000000002
				}
				sqlite3_str_appendf(&s_res, c'%06.3f', s)
			}
			int(`F`) {
				// case comp stmt
				sqlite3_str_appendf(&s_res, c'%04d-%02d-%02d', x.y, x.m_, x.d)
			}
