			}
			int(`J`) {
				// case comp stmt
				// Julian day number.  (Non-standard)

				sqlite3_str_appendf(&s_res, c'%.16g', f64(x.iJD) / 8.64E+7)
			}
			int(`m`) {
				// case comp stmt
				sqlite3_str_appendf(&s_res, c'%02d', x.m_)
			}
			int(`M`) {
				// case comp stmt
				sqlite3_str_appendf(&s_res, c'%02d', x.m)
			}
			int(`p`), int(`P`) {
				if x.h >= 12 {
					sqlite3_str_append(&s_res, unsafe { if int(cf) == i8(`p`) {
						c'PM'
					} else {
