//
//* timediff(DATE1, DATE2)
//*
//* Return the amount of time that must be added to DATE2 in order to
//* convert it into DATE2.  The time difference format is:
//*
//*     +YYYY-MM-DD HH:MM:SS.SSS
//*
//* The initial "+" becomes "-" if DATE1 occurs before DATE2.  For
//* date/time values A and B, the following invariant should hold:
//*
//*     datetime(A) == (datetime(B, timediff(A,B))
//*
//* Both DATE arguments must be either a julian day number, or an
//* ISO-8601 string.  The unix timestamps are not supported by this
//* routine.
//

@[c:'timediffFunc']
fn timediff_func(context &Sqlite3_context, not_used1 int, argv &&Sqlite3_value) {
	c2v_gc_register_thread()
	sign := i8(0)
	y := 0
	m := 0

	d1 := DateTime{}
	d2 := DateTime{}

	s_res := Sqlite3_str{}

	if is_date(context, 1, &&Sqlite3_value(unsafe { argv + 0 }), &d1) {
		return
	}
	if is_date(context, 1, &&Sqlite3_value(unsafe { argv + 1 }), &d2) {
		return
	}
	compute_ymd_hms(&d1)
	compute_ymd_hms(&d2)
	if d1.iJD >= d2.iJD {
		sign = i8(`+`)
		y = d1.y - d2.y
		if y {
			d2.y = d1.y
			d2.validJD = i8(0)
			compute_jd(&d2)
		}
		m = d1.m_ - d2.m_
		if m < 0 {
			y--
			m += 12
		}
		if m != 0 {
			d2.m_ = d1.m_
			d2.validJD = i8(0)
			compute_jd(&d2)
		}
		for d1.iJD < d2.iJD {
			m--
			if m < 0 {
				m = 11
				y--
			}
			d2.m_--
			if d2.m_ < 1 {
				d2.m_ = 12
				d2.y--
			}
			d2.validJD = i8(0)
			compute_jd(&d2)
		}
		d1.iJD -= d2.iJD
		d1.iJD += U64(1486995408) * U64(100000)
	} else {
		// d1<d2
		sign = i8(`-`)
		y = d2.y - d1.y
		if y {
			d2.y = d1.y
			d2.validJD = i8(0)
			compute_jd(&d2)
		}
		m = d2.m_ - d1.m_
		if m < 0 {
			y--
			m += 12
		}
		if m != 0 {
			d2.m_ = d1.m_
			d2.validJD = i8(0)
			compute_jd(&d2)
		}
		for d1.iJD > d2.iJD {
			m--
			if m < 0 {
				m = 11
				y--
			}
			d2.m_++
			if d2.m_ > 12 {
				d2.m_ = 1
				d2.y++
			}
			d2.validJD = i8(0)
			compute_jd(&d2)
		}
		d1.iJD = d2.iJD - d1.iJD
		d1.iJD += U64(1486995408) * U64(100000)
	}
	clear_ymd_hms_tz(&d1)
	compute_ymd_hms(&d1)
	sqlite3_str_accum_init(unsafe { &StrAccum(&s_res) }, unsafe { nil }, unsafe { nil }, 0, 100)
	sqlite3_str_appendf(&s_res, c'%c%04d-%02d-%02d %02d:%02d:%06.3f', int(sign), y, m, d1.d - 1, d1.h, d1.m, d1.s)
	sqlite3_result_str_accum(context, unsafe { &StrAccum(&s_res) })
}

