//* cases of nByte<=0 will be intercepted and dealt with by higher level
//* routines.
//

@[c:'sqlite3MemMalloc']
fn sqlite3_mem_malloc(n_byte int) voidptr {
	c2v_gc_register_thread()
	p := &voidptr(0)
	0
	p = C.malloc_zone_malloc(_sqliteZone_, usize(n_byte))
	if usize(p) == usize(0) {
		0
