//

@[c:'sqlite3StrAccumSetError']
fn sqlite3_str_accum_set_error(p &StrAccum, e_error U8) {
	p.accError = e_error
	if p.mxAlloc {
		sqlite3_str_reset(unsafe { &Sqlite3_str(p) })
	}
	if int(e_error) == 18 {
		sqlite3_error_to_parser(p.db, int(e_error))
	}
}

//
