				p.eCreate = U8(2)
			}
		}
	}
	if int(add_remove) & 2 {
		p_page.pDirtyPrev = 0
		p_page.pDirtyNext = p.pDirty
		if p_page.pDirtyNext {
			p_page.pDirtyNext.pDirtyPrev = p_page
		} else {
			p.pDirtyTail = p_page
			if p.bPurgeable {
				p.eCreate = U8(1)
			}
		}
		p.pDirty = p_page

