//

@[c:'sqlite3PcacheFetchStress']
fn sqlite3_pcache_fetch_stress(p_cache &PCache, pgno Pgno, pp_page &&Sqlite3_pcache_page) int {
	// Write result here

	p_pg := &PgHdr(0)
	if int(p_cache.eCreate) == 2 {
		return 0
	}
	if sqlite3_pcache_pagecount(p_cache) > p_cache.szSpill {
