//
//* Make sure the page is marked as clean. If it isn't clean already,
//* make it so.
//

@[c:'sqlite3PcacheMakeClean']
fn sqlite3_pcache_make_clean(p &PgHdr) {
	pcache_manage_dirty_list(p, U8(1))
	p.flags &= ~(2 | 8 | 4)
	p.flags |= 1
