		pcache1_g.szSlot = sz
		pcache1_g.nFreeSlot = n
		pcache1_g.nSlot = pcache1_g.nFreeSlot
		pcache1_g.nReserve = if n > 90 { 10 } else { (n / 10 + 1) }
