	} else {
		sz_bulk = I64(-1024) * I64(pcache1_g.nInitPage)
	}
	if sz_bulk > I64(p_cache.szAlloc) * I64(p_cache.nMax) {
		sz_bulk = I64(p_cache.szAlloc) * I64(p_cache.nMax)
	}
