				px.page.pBuf = z_bulk
				px.page.pExtra = &U8(voidptr(px)) + (((sizeof(PgHdr1)) + u64(7)) & u64(~7))
				px.isBulkLocal = U16(1)
				px.isAnchor = U16(0)
				px.pNext = p_cache.pFree
				px.pLruPrev = 0

