	p_page.pLruNext = 0

	// pPage->pLruPrev = 0;
	//  * No need to clear pLruPrev as it is never accessed if pLruNext is 0

	p_page.pCache.nRecyclable--
	return p_page
}

//
//* Remove the page supplied as an argument from the hash table
