		p_group.nMaxPage += (n - p_cache.nMax)
		p_group.mxPinned = p_group.nMaxPage + u32(10) - p_group.nMinPage
		p_cache.nMax = n
		p_cache.n90pct = p_cache.nMax * u32(9) / u32(10)
