fn btree_get_page(p_bt &BtShared, pgno Pgno, pp_page &&MemPage, flags int) int {
	// PAGER_GET_NOCONTENT or PAGER_GET_READONLY

	rc := 0
	p_db_page := &DbPage(0)
	rc = sqlite3_pager_get(p_bt.pPager, pgno, &&DbPage(c2v_address_of(&p_db_page)), flags)
	if rc {
