	rc = sqlite3_pager_get(p_bt.pPager, pgno, &&DbPage(c2v_address_of(&p_db_page)), b_read_only)
	if rc {
		unsafe { *pp_page = 0 }
		return rc
	}
	p_page = &MemPage(sqlite3_pager_get_extra(p_db_page))
