fn btree_previous(p_cur &BtCursor) int {
	rc := 0
	p_page := &MemPage(0)
	if int(p_cur.eState) != 0 {
		rc = (if int(p_cur.eState) >= 3 { btree_restore_cursor_position(p_cur) } else { 0 })
		if rc != 0 {
			return rc
		}
		if 1 == int(p_cur.eState) {
			return 101
		}
		if 2 == int(p_cur.eState) {
			p_cur.eState = U8(0)
			if p_cur.skipNext < 0 {
