fn copy_node_content(p_from &MemPage, p_to &MemPage, prc &int) {
	if (unsafe { *prc }) == 0 {
		p_bt := p_from.pBt
		a_from := p_from.aData
		a_to := p_to.aData
		i_from_hdr := int(p_from.hdrOffset)
		i_to_hdr := (if (p_to.pgno == Pgno(1)) { 100 } else { 0 })
		rc := 0
		i_data := 0

