@[c:'sqlite3ValueBytes']
fn sqlite3_value_bytes_vdup6(p_val &Sqlite3_value, enc U8) int {
	p := &Mem(p_val)
	if (int(p.flags) & 2) != 0 && int(p_val.enc) == int(enc) {
		return p.n
	}
	if (int(p.flags) & 2) != 0 && int(enc) != 1 && int(p_val.enc) != 1 {
		return p.n
	}
	if (int(p.flags) & 16) != 0 {
		if int(p.flags) & 1024 {
			return p.n + p.u.nZero
		} else {
			return p.n
		}
	}
	if int(p.flags) & 1 {
		return 0
	}
	return value_bytes(p_val, enc)
}

