	ap := C.va_list{}
	sqlite3_db_free(p.db, voidptr(p.zErrMsg))
	C.va_start(ap, z_format)
	p.zErrMsg = sqlite3_vm_printf(p.db, z_format, ap)
	C.va_end(ap)
}

