@[c:'sqlite3VdbeSwap']
fn sqlite3_vdbe_swap(pa &Vdbe, pb &Vdbe) {
	tmp := Vdbe{}
	p_tmp := &Vdbe(0)
	pp_tmp := &&Vdbe(0)

	z_tmp := &i8(0)
	tmp = unsafe { *pa }
	unsafe { *pa = *pb }
	unsafe { *pb = tmp }
	p_tmp = pa.pVNext
	pa.pVNext = pb.pVNext
	pb.pVNext = p_tmp
	pp_tmp = pa.ppVPrev
	pa.ppVPrev = pb.ppVPrev
	pb.ppVPrev = pp_tmp
	z_tmp = pa.zSql
	pa.zSql = pb.zSql
	pb.zSql = z_tmp
	pb.expmask = pa.expmask
	pb.prepFlags = pa.prepFlags
	C.memcpy(pb.aCounter, pa.aCounter, sizeof([9]u32))
	pb.aCounter[5]++
