@[c:'sqlite3VdbeAddOp4Dup8']
fn sqlite3_vdbe_add_op4_dup8(p &Vdbe, op int, p1 int, p2 int, p3 int, z_p4 &U8, p4type int) int {
	// P4 operand type

	p4copy := &i8(sqlite3_db_malloc_raw_nn(sqlite3_vdbe_db(p), U64(8)))
	if p4copy {
