//
//* This is called when the record in (*) should be found in the index
//* opened by cursor pCur, but was not. This may happen as part of a DELETE
//* operation or an integrity check.
//*
//* One reason that an exact match was not found may be the EIIB bug - that
//* a text-to-float conversion may have caused a real value in record (*)
//* to be slightly different from its counterpart on disk. This function
//* attempts to find the right index record. If it does find the right
//* record, it leaves *Cur pointing to it and sets (*Res) to 0 before
//* returning. Otherwise, (*Res) is set to non-zero and an SQLite error
//* code returned.
//*
//* The algorithm used to find the correct record is:
//*
//*   *Scan up to BTREE_FDK_RANGE entries either side of the current entry.
//*     If parameter bIntegrity is false, then all fields that are indexed
//*     expressions or virtual table columns are omitted from the comparison.
//*     If bIntegrity is true, then small differences in real values in
//*     such fields are overlooked, but they are not omitted from the comparison
//*     altogether.
//*
//*   *If the above fails to find an entry and bIntegrity is false, search
//*     the entire index.
//

@[c:'sqlite3VdbeFindIndexKey']
fn sqlite3_vdbe_find_index_key(p_cur &BtCursor, p_idx &Index, p &UnpackedRecord, p_res &int, b_integrity int) int {
	n_step := 0
	res := 1
	rc := 0
	ii := 0

	// Calculate a mask based on the first 64 columns of the index. The mask
	//  * bit is set if the corresponding index field is either an expression
	//  * or a virtual column of the table.

	mask := Bitmask(0)
	for ii = 0; ii < (if int(p_idx.nColumn) < (int((sizeof(Bitmask) * u64(8)))) {
		int(p_idx.nColumn)
	} else {
		(int((sizeof(Bitmask) * u64(8))))
	}); ii++ {
		i_col := int(p_idx.aiColumn[ii])
		if (i_col == (-2)) || (i_col >= 0 && (int(p_idx.pTable.aCol[i_col].colFlags) & 32)) {
			mask |= ((Bitmask(1)) << ii)
		}
	}

	// If the mask is 0 at this point, then the index contains no expressions
	//  * or virtual columns. So do not search for a match - return so that the
	//  * caller may declare the db corrupt immediately. Or, if mask is non-zero,
	//  * proceed.

	if mask != Bitmask(0) {
		// Move the cursor back BTREE_FDK_RANGE entries. If this hits an EOF,
		//    * position the cursor at the first entry in the index and set nStep
		//    * to -1 so that the first loop below scans the entire index. Otherwise,
		//    * set nStep to BTREE_FDK_RANGE* so that the first loop below scans
		//    * just that many entries.

		for ii = 0; sqlite3_btree_eof(p_cur) == 0 && ii < 10; ii++ {
			rc = sqlite3_btree_previous(p_cur, 0)
		}
		if rc == 101 {
			rc = sqlite3_btree_first(p_cur, &res)
			n_step = -1
		} else {
			n_step = 10 * 2
		}

		// This loop runs at most twice to search for a key with matching PK
		//    * fields in the index. The second iteration always searches the entire
		//    * index. The first iteration searches nStep entries starting with the
		//    * current cursor entry if (nStep>=0), or the entire index if (nStep<0).

		for sqlite3_btree_cursor_is_valid_nn(p_cur) {
			for ii = 0; rc == 0 && (ii < n_step || n_step < 0); ii++ {
				rc = vdbe_is_matching_index_key(p_cur, b_integrity, mask, p, &res)
				if res == 0 || rc != 0 {
					break
				}
				rc = sqlite3_btree_next(p_cur, 0)
			}
			if rc == 101 {
				rc = 0
			}
			if n_step < 0 || rc != 0 || res == 0 || b_integrity {
				break
			}

			// The first, non-exhaustive, search failed to find an entry with
			//      * matching PK fields. So restart for an exhaustive search of the
			//      * entire index.

			n_step = -1
			rc = sqlite3_btree_first(p_cur, &res)
		}
	}
	unsafe { *p_res = res }
	return rc
}

//
//* Cause a function to throw an error if it was call from OP_PureFunc
//* rather than OP_Function.
//*
//* OP_PureFunc means that the function must be deterministic, and should
//* throw an error if it is given inputs that would make it non-deterministic.
//* This routine is invoked by date/time functions that use non-deterministic
//* features such as 'now'.
//

@[c:'sqlite3NotPureFunc']
fn sqlite3_not_pure_func(p_ctx &Sqlite3_context) int {
	p_op := &VdbeOp(0)
	p_op = p_ctx.pVdbe.aOp + p_ctx.iOp
	if int(p_op.opcode) == 67 {
		z_context := &i8(0)
		z_msg := &i8(0)
		if int(p_op.p5) & 4 {
			z_context = c'a CHECK constraint'
		} else if int(p_op.p5) & 8 {
			z_context = c'a generated column'
		} else {
			z_context = c'an index'
		}
		z_msg = sqlite3_mprintf(c'non-deterministic use of %s() in %s', voidptr(p_ctx.pFunc.zName), voidptr(z_context))
		sqlite3_result_error(p_ctx, z_msg, -1)
		sqlite3_free(voidptr(z_msg))
		return 0
	}
	return 1
}

