	if int(p_mem.flags) & (4 | 8 | 32 | 1) {
		0
		0
		0
		return U16(int(p_mem.flags) & (4 | 8 | 32 | 1))
	}
	0
	0
	return compute_numeric_type(p_mem)
	return U16(0)
}

