	rc = sqlite3_os_open_malloc(db.pVfs, unsafe { nil }, pp_fd, 4096 | 2 | 4 | 16 | 8, &rc)
	if rc == 0 {
		max := I64(2147418112)
		sqlite3_os_file_control_hint((unsafe { *pp_fd }), 18, voidptr(c2v_address_of(&max)))
		if n_extend > I64(0) {
			vdbe_sorter_extend_file(db, (unsafe { *pp_fd }), n_extend)
