	}
	unsafe { *pi_eof = (p.iWriteOff + I64(p.iBufEnd)) }
	unsafe { *pn_spill += p.nPmaSpill }
	sqlite3_free(voidptr(p.aBuffer))
	rc = p.eFWErr
	C.memset(voidptr(p), 0, sizeof(PmaWriter))
