				p_merger.aTree[i] = int((i64((isize(p_readr1) - isize(p_merger.aReadr)) / isize(sizeof(PmaReader)))))
				p_readr2 = unsafe { p_merger.aReadr + p_merger.aTree[i ^ 1] }
