//* This routine also does error checking and name resolution for
//* function names.  The operator for aggregate functions is changed
//* to TK_AGG_FUNCTION.
//

@[c:'resolveExprStep']
fn resolve_expr_step(p_walker &Walker, p_expr &Expr) int {
	c2v_gc_register_thread()
	pnc := &NameContext(0)
	p_parse := &Parse(0)
	pnc = p_walker.u.pNC
	p_parse = pnc.pParse
	match p_expr.op {
