			p_src_list := pnc.pSrcList
			p_item := &SrcItem(0)
			p_item = unsafe { &p_src_list.a[0] }
			p_expr.op = U8(168)
			p_expr.y.pTab = p_item.pSTab
			p_expr.iTable = p_item.iCursor
			p_expr.iColumn--
			p_expr.affExpr = i8(68)

