			// Test of tag-20240424-1

			if int(p_item.fg.isSubquery) && (p_item.u4.pSubq.pSelect.selFlags & u32(4)) == u32(0) {
				n_ref := if p_outer_nc { p_outer_nc.nRef } else { 0 }
