	n_byte := duped_expr_struct_size(p, flags) & 4095
	if !((p.flags & u32(2048)) != u32(0)) && !isnil(p.u.zToken) {
		n_byte += (C.strlen(p.u.zToken) & u64(1073741823)) + u64(1)
	}
	return (n_byte + 7) & ~7
