		if n_vector != p_in.x.pSelect.pEList.nExpr {
			sqlite3_subselect_error(p_parse, p_in.x.pSelect.pEList.nExpr, n_vector)
			return 1
		}
	} else if n_vector != 1 {
		sqlite3_vector_error_msg(p_parse, p_in.pLeft)
		return 1
	}
	return 0
