	p_def := &FuncDef(0)
	db := &Sqlite3(0)
	if int(p_expr.op) == 158 || int(p_expr.op) == 173 || int(p_expr.op) == 114 || int(p_expr.op) == 36 {
		return 0
	}
	if int(p_expr.op) != 172 {
