	C.memset(voidptr(&w), 0, sizeof(w))
	C.memset(voidptr(&x), 0, sizeof(x))
	w.xExprCallback = expr_ref_to_src_list
	w.xSelectCallback = select_ref_enter
	w.xSelectCallback2 = select_ref_leave
