				sqlite3_rename_token_remap(p_parse, unsafe { nil }, voidptr(c2v_at(&p_list.a[0], isize(i)).zEName))
			}
		}
	}
	if p.pSrc {
		// Every Select as a SrcList, even if it is empty

		p_src := p.pSrc
