		if sqlite3_stricmp(z_type, db.init.azInit[0]) || sqlite3_stricmp(z_name, db.init.azInit[1]) || sqlite3_stricmp(z_tbl_name, db.init.azInit[2]) {
			sqlite3_error_msg(p_parse, c'')

