		p_parse.u1.cr.regRoot = c2v_prefix_add(unsafe { &p_parse.nMem }, 1)
		reg2 = p_parse.u1.cr.regRoot
		reg3 = c2v_prefix_add(unsafe { &p_parse.nMem }, 1)
