		sqlite3_may_abort(p_parse)
	}
	sqlite3_vdbe_add_op4(v, 153, i_db, 0, 0, p_tab.zName, 0)
	sqlite3_change_cookie(p_parse, i_db)
	sqlite_view_reset_all(db, i_db)
