	} else {
		z_msg = sqlite3_mp_rintf(p_parse.db, c'%s.rowid', voidptr(p_tab.zName))
		rc = (19 | (10 << 8))
	}
	sqlite3_halt_constraint(p_parse, rc, on_error, z_msg, I8((-7)), U8(2))
}

