				auto_increment_end_auto_inc_end[c2v_i_0] = c2v_element_0
			}
			auto_increment_end_auto_inc_end_inited = true
		}

		mut a_op := &VdbeOp(0)
		p_db := unsafe { db.aDb + p.iDb }
