		sqlite3_vdbe_add_op3(v, 14, addr2 + 2, i_continue, addr2 + 2)
		0
		sqlite3_vdbe_jump_here(v, addr1)
		sqlite3_vdbe_add_op3(v, 82, p_in.iSdst, reg_prev + 1, p_in.nSdst - 1)
		sqlite3_vdbe_add_op2(v, 73, 1, reg_prev)
