	match p_dest.eDest {
		// Store the result as data using a unique key.
		//
		6, 3, 12, 10 {
			r1 := sqlite3_get_temp_reg(p_parse)
			r2 := sqlite3_get_temp_reg(p_parse)
			i_parm := p_dest.iSDParm
			0
			0
			0
			0
