		sqlite3_nested_parse(p_parse, c"INSERT INTO %Q.sqlite_master VALUES('trigger',%Q,%Q,0,'CREATE TRIGGER %q')", voidptr(db.aDb[i_db].zDbSName), voidptr(z_name), voidptr(p_trig.table), voidptr(z))
