			sqlite3_oom_fault(db)
		} else if usize(p_link.pSchema) == usize(p_link.pTabSchema) {
			p_tab := &Table(0)
			p_tab = sqlite3_hash_find(&p_link.pTabSchema.tblHash, p_link.table)
			p_link.pNext = p_tab.pTrigger
