	C.memset(voidptr(&snc), 0, sizeof(snc))
	snc.pParse = p_parse
	snc.pSrcList = p_tab_list
	for ; !isnil(p_upsert) && !isnil(p_upsert.pUpsertTarget);  {
		rc = sqlite3_resolve_expr_list_names(&snc, p_upsert.pUpsertTarget)
