		p_left := unsafe { &Expr(nil) }

		res := is_auxiliary_vtab_operator(db, p_expr, &e_op2, &&Expr(&&Expr(c2v_address_of(&p_left))), &&Expr(&&Expr(c2v_address_of(&p_right))))
		for res-- > 0 {
