	p_tab := &Table(0)
	j := 0
	k := 0

	p_args := &ExprList(0)
	p_col_ref := &Expr(0)
	p_term := &Expr(0)
	if int(p_item.fg.isTabFunc) == 0 {
		return
	}
	p_tab = p_item.pSTab
	p_args = p_item.u1.pFuncArg
	if usize(p_args) == usize(0) {
		return
	}
	k = 0
	for j = 0; j < p_args.nExpr; j++ {
		p_rhs := &Expr(0)
		join_type := u32(0)
		for k < int(p_tab.nCol) && (int(p_tab.aCol[k].colFlags) & 2) == 0 {
			k++
