fn where_right_subexpr_is_column(p &Expr) &Expr {
	p = sqlite3_expr_skip_collate_and_likely(p.pRight)
	if (usize(p) != usize(0)) && int(p.op) == 168 && !((p.flags & u32(32)) != u32(0)) {
