		return 1
	}
	if (p_baseline.wsFlags & u32(512)) == u32(0) {
		return 1
	}
	if int(p_candidate.u.btree.pIndex.szIdxRow) < int(p_baseline.u.btree.pIndex.szIdxRow) {
		return 0
	}
	return 1
}

