	c2v_gc_register_thread()
	p := &CallCount(0)
	p = &CallCount(sqlite3_aggregate_context(p_ctx, int(sizeof(CallCount))))
	if p {
		p.nValue = p.nStep
		if p.nTotal > I64(1) {
			r := f64(p.nValue) / f64((p.nTotal - I64(1)))
			sqlite3_result_double(p_ctx, r)
		} else {
			sqlite3_result_double(p_ctx, 0.0)
		}
	}
}

