@[c:'windowFind']
fn window_find(p_parse &Parse, p_list &Window, z_name &i8) &Window {
	p := &Window(0)
	for p = p_list; p; p = p.pNextWin {
		if sqlite3_str_ic_mp(p.zName, z_name) == 0 {
			break
		}
	}
	if usize(p) == usize(0) {
		sqlite3_error_msg(p_parse, c'no such window: %s', voidptr(z_name))
	}
	return p
}

