			}
		} else {
			json_bad_path_error(ctx, z_path, int(j))
			unsafe { goto json_extract_error
			 }
		}
	}
	if argc > 2 {
		json_append_char(&jx, i8(`]`))
		json_return_string(&jx, unsafe { nil }, unsafe { nil })
		if (flags & 16) == 0 {
			sqlite3_result_subtype(ctx, u32(74))
		}
	}
	json_extract_error:
	json_string_reset(&jx)
	json_parse_free(p)
	return
}

