			if itv_alue >= ite_nd {
				return 1
			}
			ntv_alue = jsonb_payload_size(p_target, itv_alue, &sz_tv_alue)
			if ntv_alue == u32(0) {
				return 1
			}
			if itv_alue + ntv_alue + sz_tv_alue > ite_nd {
				return 1
			}
